import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline
import os

os.environ["CXX"] = "hipcc"

# HIP kernel for fused Residual + LayerNorm + Permute
# Input: attn_output (L, B, D), residual (L, B, D)
# Output: output (B, D, H, W)
# L = H * W
# embed_dim = D
fused_layernorm_residual_cpp_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <math.h>

__global__ void fused_layernorm_residual_kernel(
    const float* __restrict__ attn_output,
    const float* __restrict__ residual,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ output,
    int L, int B, int D, int H, int W, float eps) {

    // Each block handles one (batch, seq_len) vector of size D
    // Grid dim: (L, B)
    // Block dim: D (or a power of 2 >= D)

    int l = blockIdx.x;
    int b = blockIdx.y;
    int tid = threadIdx.x;

    if (l >= L || b >= B) return;

    // Load into shared memory for mean and variance calculation
    extern __shared__ float shared_data[];

    float val = 0.0f;
    if (tid < D) {
        int idx = (l * B + b) * D + tid;
        val = attn_output[idx] + residual[idx];
        shared_data[tid] = val;
    } else {
        shared_data[tid] = 0.0f;
    }
    __syncthreads();

    // Compute mean
    // Simple reduction for D=128
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_data[tid] += shared_data[tid + s];
        }
        __syncthreads();
    }
    float mean = shared_data[0] / D;
    __syncthreads();

    // Re-load/re-compute val to avoid using shared memory for mean
    if (tid < D) {
        int idx = (l * B + b) * D + tid;
        val = attn_output[idx] + residual[idx];
        shared_data[tid] = (val - mean) * (val - mean);
    } else {
        shared_data[tid] = 0.0f;
    }
    __syncthreads();

    // Compute variance
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_data[tid] += shared_data[tid + s];
        }
        __syncthreads();
    }
    float var = shared_data[0] / D;
    float inv_std = 1.0f / sqrtf(var + eps);

    if (tid < D) {
        // Apply LayerNorm: (val - mean) * inv_std * gamma + beta
        float out_val = (val - mean) * inv_std * gamma[tid] + beta[tid];

        // Permute to (B, D, H, W)
        // Original: (l, b, tid) where l = h*W + w
        int w = l % W;
        int h = l / W;
        // Output shape (B, D, H, W)
        // Output index: b * (D*H*W) + tid * (H*W) + h * W + w
        int out_idx = b * (D * H * W) + tid * (H * W) + h * W + w;
        output[out_idx] = out_val;
    }
}

torch::Tensor fused_layernorm_residual(
    torch::Tensor attn_output,
    torch::Tensor residual,
    torch::Tensor gamma,
    torch::Tensor beta,
    int H, int W, float eps) {

    int L = attn_output.size(0);
    int B = attn_output.size(1);
    int D = attn_output.size(2);

    auto output = torch::empty({B, D, H, W}, attn_output.options());

    // Use a power of 2 for block size >= D
    int block_size = 1;
    while (block_size < D) block_size <<= 1;

    dim3 grid(L, B);
    size_t shared_mem_size = block_size * sizeof(float);

    fused_layernorm_residual_kernel<<<grid, block_size, shared_mem_size>>>(
        attn_output.data_ptr<float>(),
        residual.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        output.data_ptr<float>(),
        L, B, D, H, W, eps);

    return output;
}
"""

fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_layernorm_residual_cpp_source,
    functions=["fused_layernorm_residual"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, embed_dim, num_heads):
        super(ModelNew, self).__init__()
        self.attn = nn.MultiheadAttention(embed_dim, num_heads)
        self.norm = nn.LayerNorm(embed_dim)
        self.embed_dim = embed_dim
        self.num_heads = num_heads

    def forward(self, x):
        B, C, H, W = x.shape
        # (B, C, H, W) -> (B, C, H*W) -> (H*W, B, C)
        x_reshaped = x.view(B, C, H * W).permute(2, 0, 1).contiguous()

        # Self-attention
        attn_output, _ = self.attn(x_reshaped, x_reshaped, x_reshaped)

        # Fused residual, layer norm, and permute back to (B, C, H, W)
        # attn_output: (L, B, D), x_reshaped: (L, B, D)
        # norm.weight: (D,), norm.bias: (D,)
        x = fused_ops.fused_layernorm_residual(
            attn_output,
            x_reshaped,
            self.norm.weight,
            self.norm.bias,
            H, W,
            self.norm.eps
        )
        return x

