    __syncthreads();

    // Reduction for mean
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_data[tid] += shared_data[tid + s];
        }
        __syncthreads();
    }
    float mean = shared_data[0] / C;
    __syncthreads();

    // Reset shared_data for variance calculation
    if (tid < C) {
        float diff = val - mean;
        shared_data[tid] = diff * diff;
    } else {
        shared_data[tid] = 0.0f;
    }
    __syncthreads();

    // Reduction for variance
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_data[tid] += shared_data[tid + s];
        }
        __syncthreads();
    }
    float var = shared_data[0] / C;
    float inv_std = 1.0f / sqrtf(var + eps);

    if (tid < C) {
        float out_val = (val - mean) * inv_std * gamma[tid] + beta[tid];
        int h = l / W;
        int w = l % W;
        // Output (B, C, H, W)
        int out_idx = ((b * C + tid) * H + h) * W + w;
