    fused_layernorm_residual_kernel<<<grid, block_size, shared_mem_size>>>(
        attn_output.data_ptr<float>(),
        residual.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        output.data_ptr<float>(),
        B, L, C, H, W, eps);

    return output;
}
